1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  :root {
9	    --bg: #111418;
10	    --panel: #1b2027;
11	    --grid: #232a33;
12	    --text: #e8ecf1;
13	    --muted: #8b96a5;
14	    --I: #22c7e8;
15	    --O: #f2c613;
16	    --T: #a64ee0;
17	    --S: #3fc15a;
18	    --Z: #e8453c;
19	    --J: #3a6fe8;
20	    --L: #f08a24;
21	  }
22	  * { box-sizing: border-box; }
23	  body {
24	    margin: 0;
25	    min-height: 100vh;
26	    background: var(--bg);
27	    color: var(--text);
28	    font: 15px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
29	    display: flex;
30	    align-items: center;
31	    justify-content: center;
32	    padding: 16px;
33	  }
34	  .game { display: flex; gap: 20px; align-items: flex-start; flex-wrap: wrap; justify-content: center; }
35	  .board {
36	    display: grid;
37	    grid-template-columns: repeat(10, 28px);
38	    grid-template-rows: repeat(20, 28px);
39	    gap: 1px;
40	    background: var(--grid);
41	    border: 2px solid var(--grid);
42	    border-radius: 4px;
43	  }
44	  .cell { background: var(--bg); }
45	  .side { display: flex; flex-direction: column; gap: 12px; min-width: 140px; }
46	  .box { background: var(--panel); border-radius: 6px; padding: 10px 12px; }
47	  .label { color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: .08em; }
48	  .value { font-size: 22px; font-weight: 600; font-variant-numeric: tabular-nums; }
49	  .preview {
50	    display: grid;
51	    grid-template-columns: repeat(4, 20px);
52	    grid-template-rows: repeat(2, 20px);
53	    gap: 1px;
54	    margin-top: 6px;
55	  }
56	  .preview div { background: transparent; }
57	  .next-list { display: flex; flex-direction: column; gap: 8px; }
58	  .board-wrap { position: relative; }
59	  .game-over {
60	    position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
61	    background: rgba(17, 20, 24, .78); font-size: 24px; font-weight: 600; border-radius: 4px;
62	  }
63	  .p-I { background: var(--I) !important; }
64	  .p-O { background: var(--O) !important; }
65	  .p-T { background: var(--T) !important; }
66	  .p-S { background: var(--S) !important; }
67	  .p-Z { background: var(--Z) !important; }
68	  .p-J { background: var(--J) !important; }
69	  .p-L { background: var(--L) !important; }
70	  button {
71	    background: var(--panel); color: var(--text); border: 1px solid var(--grid);
72	    border-radius: 6px; padding: 8px 12px; font: inherit; cursor: pointer;
73	  }
74	  button:hover { border-color: var(--muted); }
75	  .keys { color: var(--muted); font-size: 13px; }
76	</style>
77	</head>
78	<body>
79	<div class="game">
80	  <div class="board-wrap">
81	    <div class="board" data-testid="board" id="board"></div>
82	    <div class="game-over" data-testid="game-over" id="game-over" hidden>Game over</div>
83	  </div>
84	  <div class="side">
85	    <div class="box"><div class="label">Score</div><div class="value" data-testid="score" id="score">0</div></div>
86	    <div class="box"><div class="label">Level</div><div class="value" data-testid="level" id="level">1</div></div>
87	    <div class="box"><div class="label">Lines</div><div class="value" data-testid="lines" id="lines">0</div></div>
88	    <div class="box"><div class="label">Next</div><div class="next-list" data-testid="next-piece" id="preview"></div></div>
89	    <button id="restart" type="button">New game</button>
90	    <div class="keys">← → move<br>↑ rotate<br>↓ soft drop<br>Space hard drop</div>
91	  </div>
92	</div>
93	<script>
94	(function () {
95	  "use strict";
96	
97	  var ROWS = 20, COLS = 10;
98	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
99	
100	  // Spawn shapes as [row, col] offsets from the piece origin.
101	  var SHAPES = {
102	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
103	    O: [[0, 1], [0, 2], [1, 1], [1, 2]],
104	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
105	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
106	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
107	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
108	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
109	  };
110	  // Side length of the square each shape rotates within.
111	  var BOX = { I: 4, O: 2, T: 3, S: 3, Z: 3, J: 3, L: 3 };
112	  var SPAWN_COL = 3;
113	  var GRAVITY_MS = 1000;
114	  var PREVIEW_COUNT = 3;
115	
116	  // Locking rule (project decision): a gravity step that cannot move the piece
117	  // down counts one lock tick; the piece locks on the LOCK_TICKS-th tick.
118	  // Left/right while resting restarts the delay, at most MAX_LOCK_RESETS times
119	  // per piece. Hard drop locks at once.
120	  var LOCK_TICKS = 2;
121	  var MAX_LOCK_RESETS = 3;
122	  // Rotation tries these sideways shifts, in order, until one fits.
123	  var KICKS = [0, -1, 1, -2, 2];
124	
125	  // Scoring rule (project decision): a clear scores CLEAR_POINTS[rows] x level.
126	  // Clearing rows together must always beat clearing them one at a time.
127	  // Soft drop scores 1 per cell moved by the player (gravity scores nothing);
128	  // hard drop scores 2 per cell dropped. Drop points are not multiplied.
129	  var CLEAR_POINTS = [0, 100, 300, 500, 800];
130	  var SOFT_DROP_POINTS = 1;
131	  var HARD_DROP_POINTS = 2;
132	
133	  var state = {
134	    board: [],      // ROWS x COLS, "" or piece letter
135	    current: null,  // { type, row, col, shape, lockTicks, lockResets }
136	    next: [],
137	    score: 0,
138	    level: 1,
139	    lines: 0,
140	    status: "running"
141	  };
142	
143	  // ---- core logic ----
144	
145	  function emptyBoard() {
146	    var b = [];
147	    for (var r = 0; r < ROWS; r++) {
148	      var row = [];
149	      for (var c = 0; c < COLS; c++) row.push("");
150	      b.push(row);
151	    }
152	    return b;
153	  }
154	
155	  function randomType() {
156	    return TYPES[Math.floor(Math.random() * TYPES.length)];
157	  }
158	
159	  function cellsOf(piece, dRow, dCol) {
160	    return piece.shape.map(function (o) {
161	      return [piece.row + (dRow || 0) + o[0], piece.col + (dCol || 0) + o[1]];
162	    });
163	  }
164	
165	  function fits(piece, dRow, dCol) {
166	    return cellsOf(piece, dRow, dCol).every(function (p) {
167	      return p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS && state.board[p[0]][p[1]] === "";
168	    });
169	  }
170	
171	  function spawn() {
172	    var type = state.next.length ? state.next.shift() : randomType();
173	    while (state.next.length < PREVIEW_COUNT) state.next.push(randomType());
174	    var piece = { type: type, row: 0, col: SPAWN_COL, shape: SHAPES[type], lockTicks: 0, lockResets: 0 };
175	    // Game over: the new piece has nowhere to go. It is not placed.
176	    if (!fits(piece, 0, 0)) {
177	      state.current = null;
178	      state.status = "gameover";
179	      return;
180	    }
181	    state.current = piece;
182	  }
183	
184	  function lock() {
185	    var piece = state.current;
186	    cellsOf(piece).forEach(function (p) { state.board[p[0]][p[1]] = piece.type; });
187	    state.current = null;
188	    clearLines();
189	    spawn();
190	  }
191	
192	  // Remove every full row; rows above drop down. Scores the clear.
193	  function clearLines() {
194	    var kept = state.board.filter(function (row) {
195	      return row.some(function (t) { return t === ""; });
196	    });
197	    var cleared = ROWS - kept.length;
198	    if (!cleared) return;
199	    while (kept.length < ROWS) kept.unshift(emptyBoard()[0]);
200	    state.board = kept;
201	    state.lines += cleared;
202	    state.score += CLEAR_POINTS[cleared] * state.level;
203	  }
204	
205	  function tryMove(dRow, dCol) {
206	    if (!state.current || !fits(state.current, dRow, dCol)) return false;
207	    state.current.row += dRow;
208	    state.current.col += dCol;
209	    if (dRow > 0) state.current.lockTicks = 0;
210	    return true;
211	  }
212	
213	  // Sideways move. If the lock delay is running, restart it (capped per piece).
214	  function shift(dCol) {
215	    var piece = state.current;
216	    if (!tryMove(0, dCol)) return;
217	    if (piece.lockTicks > 0 && piece.lockResets < MAX_LOCK_RESETS) {
218	      piece.lockResets++;
219	      piece.lockTicks = 0;
220	    }
221	  }
222	
223	  function rotateCW() {
224	    var piece = state.current;
225	    if (!piece || piece.type === "O") return;
226	    var n = BOX[piece.type];
227	    var turned = {
228	      type: piece.type, row: piece.row, col: piece.col,
229	      shape: piece.shape.map(function (o) { return [o[1], n - 1 - o[0]]; })
230	    };
231	    for (var i = 0; i < KICKS.length; i++) {
232	      if (fits(turned, 0, KICKS[i])) {
233	        piece.shape = turned.shape;
234	        piece.col += KICKS[i];
235	        return;
236	      }
237	    }
238	  }
239	
240	  // One gravity step. The timer and __tetris.tick both call this.
241	  function gravityStep() {
242	    if (state.status !== "running" || !state.current) return;
243	    if (tryMove(1, 0)) return;
244	    state.current.lockTicks++;
245	    if (state.current.lockTicks >= LOCK_TICKS) lock();
246	  }
247	
248	  var actions = {
249	    left: function () { if (state.current) shift(-1); },
250	    right: function () { if (state.current) shift(1); },
251	    rotateCW: rotateCW,
252	    softDrop: function () {
253	      if (tryMove(1, 0)) state.score += SOFT_DROP_POINTS;
254	    },
255	    hardDrop: function () {
256	      if (!state.current) return;
257	      while (tryMove(1, 0)) state.score += HARD_DROP_POINTS;
258	      lock();
259	    }
260	  };
261	
262	  function doAction(name) {
263	    if (state.status !== "running" || !actions[name]) return;
264	    actions[name]();
265	    render();
266	  }
267	
268	  function newGame(queue) {
269	    state.board = emptyBoard();
270	    state.score = 0;
271	    state.level = 1;
272	    state.lines = 0;
273	    state.status = "running";
274	    state.next = Array.isArray(queue) ? queue.slice() : [];
275	    spawn();
276	    restartTimer();
277	    render();
278	  }
279	
280	  // ---- rendering (synchronous) ----
281	
282	  var boardEl = document.getElementById("board");
283	  var previewEl = document.getElementById("preview");
284	  var scoreEl = document.getElementById("score");
285	  var levelEl = document.getElementById("level");
286	  var linesEl = document.getElementById("lines");
287	  var gameOverEl = document.getElementById("game-over");
288	  var cellEls = [];
289	
290	  (function buildDom() {
291	    for (var r = 0; r < ROWS; r++) {
292	      var row = [];
293	      for (var c = 0; c < COLS; c++) {
294	        var el = document.createElement("div");
295	        el.className = "cell";
296	        el.setAttribute("data-testid", "cell");
297	        el.setAttribute("data-row", String(r));
298	        el.setAttribute("data-col", String(c));
299	        el.setAttribute("data-filled", "false");
300	        el.setAttribute("data-piece", "");
301	        boardEl.appendChild(el);
302	        row.push(el);
303	      }
304	      cellEls.push(row);
305	    }
306	  })();
307	
308	  // One preview item per upcoming piece, soonest first, drawn in its board colour.
309	  function previewItem(type) {
310	    var item = document.createElement("div");
311	    item.className = "preview";
312	    item.setAttribute("data-testid", "next-piece-item");
313	    item.setAttribute("data-piece", type);
314	    var cells = [];
315	    for (var i = 0; i < 8; i++) cells.push(item.appendChild(document.createElement("div")));
316	    SHAPES[type].forEach(function (o) { paint(cells[o[0] * 4 + o[1]], type); });
317	    return item;
318	  }
319	
320	  function paint(el, type) {
321	    el.className = el.className.replace(/\s*p-[A-Z]/g, "") + (type ? " p-" + type : "");
322	  }
323	
324	  function render() {
325	    var view = state.board.map(function (row) { return row.slice(); });
326	    if (state.current) {
327	      cellsOf(state.current).forEach(function (p) {
328	        if (p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS) view[p[0]][p[1]] = state.current.type;
329	      });
330	    }
331	    for (var r = 0; r < ROWS; r++) {
332	      for (var c = 0; c < COLS; c++) {
333	        var el = cellEls[r][c], t = view[r][c];
334	        el.setAttribute("data-filled", t ? "true" : "false");
335	        el.setAttribute("data-piece", t);
336	        paint(el, t);
337	      }
338	    }
339	    previewEl.textContent = "";
340	    state.next.slice(0, PREVIEW_COUNT).forEach(function (type) {
341	      if (SHAPES[type]) previewEl.appendChild(previewItem(type));
342	    });
343	    gameOverEl.hidden = state.status !== "gameover";
344	    scoreEl.textContent = String(state.score);
345	    levelEl.textContent = String(state.level);
346	    linesEl.textContent = String(state.lines);
347	  }
348	
349	  // ---- timer ----
350	
351	  var timer = null;
352	  function onTimer() { gravityStep(); render(); }
353	  function restartTimer() {
354	    if (timer) clearInterval(timer);
355	    timer = setInterval(onTimer, GRAVITY_MS);
356	  }
357	
358	  // ---- input ----
359	
360	  var KEYS = { ArrowLeft: "left", ArrowRight: "right", ArrowDown: "softDrop", ArrowUp: "rotateCW", " ": "hardDrop" };
361	  document.addEventListener("keydown", function (e) {
362	    var action = KEYS[e.key];
363	    if (!action) return;
364	    e.preventDefault();
365	    doAction(action);
366	  });
367	  document.getElementById("restart").addEventListener("click", function (e) {
368	    e.currentTarget.blur();
369	    newGame();
370	  });
371	
372	  // ---- test control surface ----
373	
374	  window.__tetris = {
375	    newGame: function (queue) { newGame(queue); },
376	    setQueue: function (queue) {
377	      state.next = Array.isArray(queue) ? queue.slice() : [];
378	      render();
379	    },
380	    setBoard: function (rows) {
381	      state.board = rows.map(function (line) {
382	        return line.split("").map(function (ch) { return ch === "." ? "" : ch; });
383	      });
384	      render();
385	    },
386	    tick: function (n) {
387	      var steps = n === undefined ? 1 : n;
388	      for (var i = 0; i < steps; i++) gravityStep();
389	      render();
390	    },
391	    input: function (action) { doAction(action); },
392	    getBoard: function () {
393	      return state.board.map(function (row) {
394	        return row.map(function (t) { return t || "."; }).join("");
395	      });
396	    },
397	    getState: function () {
398	      return {
399	        current: state.current
400	          ? { type: state.current.type, cells: cellsOf(state.current) }
401	          : null,
402	        next: state.next.slice(),
403	        score: state.score,
404	        level: state.level,
405	        lines: state.lines,
406	        status: state.status
407	      };
408	    }
409	  };
410	
411	  newGame();
412	})();
413	</script>
414	</body>
415	</html>
